package atorch.shortestpaths;

import android.content.Context;
import android.graphics.Path;
import android.graphics.RectF;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Country polygons for the map screen, read from assets/world_map.bin.
 *
 * The asset is generated by scripts/build_world_map.py from Natural Earth (public domain) data;
 * see that script for the binary format. Coordinates are Web Mercator, normalized to the unit
 * square: x in [0, 1] from 180W to 180E, y in [0, 1] from north to south.
 */
public class WorldMap {

    private static final String ASSET_NAME = "world_map.bin";
    private static WorldMap instance;

    public static class Feature {
        public final String code;  // Natural Earth ADM0_A3 code, e.g. "FRA" (or our own "GUF" / "KAL")
        public final String label;  // Puzzle country name to draw, or "" if this unit is not labelled
        public final float labelX;
        public final float labelY;
        public final float[][][] lods;  // lods[lod][ring] = {x0, y0, x1, y1, ...}, coarsest LOD first
        public final RectF bounds = new RectF();
        public final float area;  // Approximate (bounding box) area, used for draw & label order
        private final Path[] paths;

        Feature(String code, String label, float labelX, float labelY, float[][][] lods) {
            this.code = code;
            this.label = label;
            this.labelX = labelX;
            this.labelY = labelY;
            this.lods = lods;
            this.paths = new Path[lods.length];
            float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE;
            float maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
            for (float[] ring : lods[lods.length - 1]) {
                for (int i = 0; i < ring.length; i += 2) {
                    minX = Math.min(minX, ring[i]);
                    maxX = Math.max(maxX, ring[i]);
                    minY = Math.min(minY, ring[i + 1]);
                    maxY = Math.max(maxY, ring[i + 1]);
                }
            }
            bounds.set(minX, minY, maxX, maxY);
            area = bounds.width() * bounds.height();
        }

        public boolean isLabelled() {
            return label.length() > 0;
        }

        /** Lazily builds (and caches) an android Path for the given level of detail. */
        public Path getPath(int lod) {
            if (paths[lod] == null) {
                Path path = new Path();
                path.setFillType(Path.FillType.EVEN_ODD);  // Holes (e.g. Lesotho inside South Africa)
                for (float[] ring : lods[lod]) {
                    path.moveTo(ring[0], ring[1]);
                    for (int i = 2; i < ring.length; i += 2) {
                        path.lineTo(ring[i], ring[i + 1]);
                    }
                    path.close();
                }
                paths[lod] = path;
            }
            return paths[lod];
        }

        /** Even-odd point-in-polygon test, in map coordinates, against the finest LOD. */
        public boolean contains(float x, float y) {
            if (!bounds.contains(x, y)) {
                return false;
            }
            boolean inside = false;
            for (float[] ring : lods[lods.length - 1]) {
                int n = ring.length;
                for (int i = 0, j = n - 2; i < n; j = i, i += 2) {
                    float xi = ring[i], yi = ring[i + 1], xj = ring[j], yj = ring[j + 1];
                    if ((yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) {
                        inside = !inside;
                    }
                }
            }
            return inside;
        }
    }

    public final List<Feature> features;
    private final Map<String, int[]> aliases;  // Puzzle country name -> feature indices (first is primary)
    private final Map<Feature, String> countryNames = new HashMap<>();  // Map unit -> puzzle country name
    public final float[] lodTolerances;  // Simplification tolerance of each LOD, coarsest first
    public final RectF bounds = new RectF();  // Union of all features

    private WorldMap(List<Feature> features, Map<String, int[]> aliases, float[] lodTolerances) {
        this.features = features;
        this.aliases = aliases;
        this.lodTolerances = lodTolerances;
        // Unlabelled units that belong to a puzzle country, e.g. Saint-Martin (France), Akrotiri (United Kingdom)
        for (Map.Entry<String, int[]> entry : aliases.entrySet()) {
            for (int index : entry.getValue()) {
                Feature feature = features.get(index);
                if (!feature.isLabelled()) {
                    countryNames.put(feature, entry.getKey());
                }
            }
        }
        bounds.set(features.get(0).bounds);
        for (Feature feature : features) {
            bounds.union(feature.bounds);
        }
    }

    /** The puzzle country a map unit belongs to, or null (e.g. Greenland, Western Sahara). */
    public String countryNameFor(Feature feature) {
        if (feature.isLabelled()) {
            return feature.label;
        }
        return countryNames.get(feature);
    }

    /** Index of the coarsest LOD whose simplification error is below maxErrorPx at this zoom. */
    public int lodFor(float pixelsPerUnit, float maxErrorPx) {
        for (int lod = 0; lod < lodTolerances.length; lod++) {
            if (lodTolerances[lod] * pixelsPerUnit <= maxErrorPx) {
                return lod;
            }
        }
        return lodTolerances.length - 1;
    }

    public static synchronized WorldMap get(Context context) throws IOException {
        if (instance == null) {
            instance = parse(readAsset(context));
        }
        return instance;
    }

    /** All map units that make up a puzzle country (empty if unknown). */
    public List<Feature> featuresFor(String countryName) {
        List<Feature> result = new ArrayList<>();
        int[] indices = aliases.get(countryName);
        if (indices != null) {
            for (int index : indices) {
                result.add(features.get(index));
            }
        }
        return result;
    }

    /** The map unit that carries a puzzle country's label, or null if unknown. */
    public Feature primaryFeatureFor(String countryName) {
        int[] indices = aliases.get(countryName);
        return (indices == null || indices.length == 0) ? null : features.get(indices[0]);
    }

    private static byte[] readAsset(Context context) throws IOException {
        InputStream in = context.getAssets().open(ASSET_NAME);
        try {
            ByteArrayOutputStream out = new ByteArrayOutputStream(1 << 20);
            byte[] buffer = new byte[1 << 16];
            int n;
            while ((n = in.read(buffer)) > 0) {
                out.write(buffer, 0, n);
            }
            return out.toByteArray();
        } finally {
            in.close();
        }
    }

    static WorldMap parse(byte[] data) throws IOException {
        ByteBuffer buf = ByteBuffer.wrap(data);  // Big-endian by default, matching the script
        if (buf.get() != 'S' || buf.get() != 'P' || buf.get() != 'W' || buf.get() != 'M') {
            throw new IOException("Not a world map file");
        }
        int version = buf.get();
        if (version != 1) {
            throw new IOException("Unsupported world map version " + version);
        }
        float quantScale = 1.0f / (1 << readVarint(buf));
        int lodCount = readVarint(buf);
        float[] lodTolerances = new float[lodCount];
        for (int lod = 0; lod < lodCount; lod++) {
            lodTolerances[lod] = buf.getFloat();
        }
        int featureCount = readVarint(buf);

        List<Feature> features = new ArrayList<>(featureCount);
        for (int f = 0; f < featureCount; f++) {
            String code = readString(buf);
            String label = readString(buf);
            float labelX = buf.getFloat();
            float labelY = buf.getFloat();
            float[][][] lods = new float[lodCount][][];
            for (int lod = 0; lod < lodCount; lod++) {
                int ringCount = readVarint(buf);
                float[][] rings = new float[ringCount][];
                for (int r = 0; r < ringCount; r++) {
                    int pointCount = readVarint(buf);
                    float[] ring = new float[2 * pointCount];
                    int x = 0, y = 0;
                    for (int i = 0; i < pointCount; i++) {
                        x += readZigzag(buf);
                        y += readZigzag(buf);
                        ring[2 * i] = x * quantScale;
                        ring[2 * i + 1] = y * quantScale;
                    }
                    rings[r] = ring;
                }
                lods[lod] = rings;
            }
            features.add(new Feature(code, label, labelX, labelY, lods));
        }

        int aliasCount = readVarint(buf);
        Map<String, int[]> aliases = new HashMap<>();
        for (int a = 0; a < aliasCount; a++) {
            String name = readString(buf);
            int[] indices = new int[readVarint(buf)];
            for (int i = 0; i < indices.length; i++) {
                indices[i] = readVarint(buf);
            }
            aliases.put(name, indices);
        }
        return new WorldMap(features, aliases, lodTolerances);
    }

    private static int readVarint(ByteBuffer buf) {
        int result = 0;
        int shift = 0;
        while (true) {
            int b = buf.get() & 0xFF;
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
            shift += 7;
        }
    }

    private static int readZigzag(ByteBuffer buf) {
        int v = readVarint(buf);
        return (v >>> 1) ^ -(v & 1);
    }

    private static String readString(ByteBuffer buf) throws IOException {
        byte[] bytes = new byte[readVarint(buf)];
        buf.get(bytes);
        return new String(bytes, "UTF-8");
    }
}
